"""Asociaciones reales con registros DESARROLLO previamente creados; no limpia tablas."""
import json,uuid,unittest,base64,urllib.request,urllib.parse,subprocess
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
class RelacionesClinica(unittest.TestCase):
 def test_tipos_examenes_y_secuencias(self):
  a=json.loads(Path('/Users/albertoalexanderitzepsarceno/Library/Application Support/GalenosSV/credentials.json').read_text())['administrador-local'];auth='Basic '+base64.b64encode((a['username']+':'+a['password']).encode()).decode()
  def get(path):
   with urllib.request.urlopen(urllib.request.Request('http://localhost:9080/GalenosSV/resources/v2/'+path,headers={'Authorization':auth}))as r:return json.load(r)
  exam=next(e for e in get('examen?max=100') if e['nombre'].startswith('DESARROLLO examen flujo') and e['activo']);proc=next(e for e in get('procedimiento?max=100') if e['nombre'].startswith('DESARROLLO procedimiento flujo') and e['activo']);steps=get('procedimiento_paso?idProcedimiento='+proc['idProcedimiento']);first=next(s for s in steps if s['nombre']=='Inicio Desarrollo');last=next(s for s in steps if s['nombre']=='Fin Desarrollo')
  with sync_playwright()as p:
   b=p.chromium.launch(headless=True);page=b.new_page(viewport={'width':1440,'height':1100});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://localhost:3000');page.locator('[data-module=tipoExamen]').click();page.locator('#gestion-usuario').fill(a['username']);page.locator('#gestion-clave').fill(a['password']);page.get_by_role('button',name='Iniciar sesión',exact=True).click();expect(page.locator('[data-catalogos] .gestion-tools').first).to_be_visible()
   typeName='DESARROLLO tipo '+uuid.uuid4().hex[:8];page.get_by_role('button',name='Nuevo registro',exact=True).click();d=page.locator('#gestion dialog:visible');d.locator('[name=nombre]').fill(typeName);d.locator('[name=activo]').check();d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible()
   page.locator('[data-module=examen]').click();page.locator('[data-catalogos] input[type=search]').fill(exam['nombre']);page.get_by_role('button',name='Buscar',exact=True).click();page.locator('[data-catalogos] tbody tr').filter(has_text=exam['nombre']).get_by_role('button',name='Tipos de examen',exact=True).click();page.get_by_role('button',name='Nueva asociación',exact=True).click();d=page.locator('#gestion dialog:visible');expect(d.locator('[name=idTipoExamen] option').nth(1)).to_be_attached();d.locator('[name=idTipoExamen]').select_option(label=typeName);d.locator('[name=observaciones]').fill('DESARROLLO asociación');d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible();expect(page.locator('#gestion')).to_contain_text(typeName)
   # Se edita la asociación creada por esta prueba y se elimina exclusivamente su fila.
   line=page.locator('#gestion .gestion-tools:visible').filter(has_text=typeName);line.get_by_role('button',name='Editar',exact=True).click();d.locator('[name=observaciones]').fill('DESARROLLO edición asociación');d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible();page.once('dialog',lambda x:x.accept());line.get_by_role('button',name='Quitar asociación',exact=True).click();expect(line).to_have_count(0)
   page.locator('[data-module=procedimiento]').click();page.locator('[data-catalogos] input[type=search]').fill(proc['nombre']);page.get_by_role('button',name='Buscar',exact=True).click();page.locator('[data-catalogos] tbody tr').filter(has_text=proc['nombre']).get_by_role('button',name='Gestionar pasos',exact=True).click();stepLine=page.locator('#gestion .gestion-tools:visible').filter(has_text='Inicio Desarrollo');stepLine.get_by_role('button',name='Exámenes asociados',exact=True).click();relation=page.locator('#gestion .gestion-tools:visible').filter(has_text=exam['nombre']);relation.get_by_role('button',name='Editar',exact=True).click();d=page.locator('#gestion dialog:visible');d.locator('[name=observaciones]').fill('DESARROLLO examen de paso editado');d.locator('[name=activo]').uncheck();d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible();self.assertFalse(get('procedimiento_paso_examen?idProcedimientoPaso='+first['idProcedimientoPaso'])[0]['activo'])
   page.get_by_role('button',name='Volver',exact=True).click();stepLine=page.locator('#gestion .gestion-tools:visible').filter(has_text='Inicio Desarrollo');stepLine.get_by_role('button',name='Secuencias',exact=True).click();page.locator('#gestion .gestion-tools:visible').filter(has_text='Fin Desarrollo').get_by_role('button',name='Editar',exact=True).click();d=page.locator('#gestion dialog:visible');d.locator('[name=tipoSecuencia]').fill('DESARROLLO');d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible();self.assertEqual(get('procedimiento_paso_secuencia?idProcedimientoPaso='+first['idProcedimientoPaso'])[0]['tipoSecuencia'],'DESARROLLO')
   page.get_by_role('button',name='Volver',exact=True).click();page.locator('#gestion .gestion-tools:visible').filter(has_text='Fin Desarrollo').get_by_role('button',name='Secuencias',exact=True).click();page.get_by_role('button',name='Nueva asociación',exact=True).click();d=page.locator('#gestion dialog:visible');d.locator('[name=idProcedimientoPasoReferencia]').select_option(first['idProcedimientoPaso']);d.get_by_role('button',name='Guardar',exact=True).click();expect(d.locator('[role=alert]')).not_to_be_empty();expect(d).to_be_visible();self.assertEqual(get('procedimiento_paso_secuencia?idProcedimientoPaso='+last['idProcedimientoPaso']),[]);d.get_by_role('button',name='Cancelar',exact=True).click()
   uuid.UUID(first['idProcedimientoPaso']);sql="SELECT count(*) FROM procedimiento_paso_examen WHERE id_procedimiento_paso='"+first['idProcedimientoPaso']+"' AND activo IS FALSE AND observaciones='DESARROLLO examen de paso editado'";count=subprocess.check_output(['docker','exec','postgres_db','psql','-U','postgres','-d','clinica','-At','-c',sql],text=True).strip();self.assertEqual(count,'1');self.assertEqual(errors,[]);b.close()
if __name__=='__main__':unittest.main(verbosity=2)
